from ta_moler.device.egate import Egate
from moler.helpers import call_base_class_method_with_same_name


@call_base_class_method_with_same_name
class EPCSim(Egate):
    r"""
    Epcsim device class.

    Example of device in yaml configuration file:
    - with PROXY_PC:
      EPCSIM_PROXY_PC:
        DEVICE_CLASS: ta_moler.device.epcsim.EPCSim
        INITIAL_STATE: UNIX_LOCAL
        CONNECTION_HOPS:
          UNIX_LOCAL:
            PROXY_PC:
              execute_command: ssh
              command_params:
                expected_prompt: "proxy_pc#"
                host: proxy_pc_host
                login: proxy_pc_login
                password: password
                set_timeout: null
          EPCSIM:
            PROXY_PC:
              execute_command: exit
              command_params:
                expected_prompt: "proxy_pc#"
          EPCSIM_UNIX:
            PROXY_PC:
              execute_command: exit
              command_params:
                expected_prompt: "proxy_pc#"

          PROXY_PC:
            EPCSIM:
              execute_command: telnet
              command_params:
                expected_prompt: "EGATE>"
            EGATE_UNIX:
              execute_command: ssh
              command_params:
                host: egate_ip
            UNIX_LOCAL:
              execute_command: exit
              command_params:
                expected_prompt: "moler_bash#"

    - without PROXY_PC:
      EPCSIM:
        DEVICE_CLASS: ta_moler.device.epcsim.EPCSim
        INITIAL_STATE: UNIX_LOCAL
        CONNECTION_HOPS:
          UNIX_LOCAL:
            EPCSIM:
              execute_command: telnet
              command_params:
                expected_prompt: "EGATE>"
                host: epc_host
            EGATE_UNIX:
              execute_command: ssh
              command_params:
                host: epc_host
          EPCSIM:
            UNIX_LOCAL:
              execute_command: exit
              command_params:
                expected_prompt: "moler_bash#"
    """

    egate = "EPCSIM"
    epcsim = "EPCSIM"

    egate_unix = "EPCSIM_UNIX"
    epcsim_unix = "EPCSIM_UNIX"
